  "m1347": "LLM rotation · Failover",
  "m1348": "When enabled, ",
  "m1349": "Agents without a specified model",
  "m1350": "automatically switch to the next profile when the current one is unavailable (insufficient balance / invalid key / rate limit / service error).",
  "m1351": "Enable rotation",
  "m1352": "Off by default. When off, only the active profile is used and failures remain failures.",
  "m1353": "LLM rotation toggle",
  "m1354": "Also fall back when a specified model fails",
  "m1355": "Off by default: an Agent or task bound to a profile uses only that profile, without silently switching models on failure. Enable to fall back to the rotation chain below when the specified profile fails.",
  "m1356": "Bound-profile failure fallback toggle",
  "m1357": "Rotation order",
  "m1358": "Restore all",
  "m1359": "Only",
  "m1360": "profiles available; rotation requires at least two profiles with API keys and rotation enabled.",
  "m1361": "Active",
