  "m1363": "Cooldown",
  "m1364": "Consecutive failures",
  "m1365": "times",
  "m1366": "Restore now",
  "m1367": "Restore now: clear the circuit breaker and retry this profile on the next call",
  "m1368": "No profiles yet",
  "m1369": "The active profile is always first; others follow descending priority set in each profile. Failed profiles cool down (60s → 5min → 30min) and are skipped, then automatically rejoin. Profiles with insufficient context windows are skipped. Agents and tasks with specified models do not rotate by default.",
