  "m1644": "System settings",
  "m1645": "Global runtime switches",
  "m1646": "When enabled, all Agent HTTP traffic passes through the recording proxy and is stored. Agents receive traffic_search / traffic_get tools and proxy settings, including proxy instructions in their prompts.",
  "m1647": "When disabled (default), no traffic is recorded. Agents",
  "m1648": "do not",
  "m1649": "receive proxy settings or traffic tools, and prompts",
  "m1650": "exclude",
  "m1651": "proxy instructions. Switching rebuilds Agents immediately to apply the change.",
  "m1652": "Enabled · Recording traffic and injecting proxy settings",
  "m1653": "Disabled · No recording or proxy injection",
  "m1654": "Agent automatic traffic binding",
  "m1655": "Off by default. When enabled, the report Agent triggered on vulnerability creation reviews existing HTTP requests/responses and links traffic before writing the report.",
  "m1656": "Inspecting packets and making extra tool calls increases token usage.",
  "m1657": "TCP, uncaptured, or unmatched traffic can still be reported. This does not affect capture, manual binding, or viewing saved evidence. Applies to the next Agent round; disabling immediately rejects new automatic bindings.",
  "m1658": "Enabled · Increases token usage",
  "m1659": "Disabled · Manual binding remains available",
  "m1660": "Global proxy",
  "m1661": "All Agents'",
  "m1662": "target traffic",
  "m1663": "uses this outbound proxy (hide source IP / use a jump host). Supports",
  "m1664": "with optional",
  "m1665": "authentication. Blank = direct connection.",
  "m1666": "is enabled, it acts as the recording proxy's",
  "m1667": "upstream",
  "m1668": "(traffic is still recorded before forwarding). With capture off, proxy settings are injected directly into Agent Bash/WebFetch. Independent of web search and LLM proxies.",
  "m1669": ": SOCKS5 with",
  "m1670": "capture disabled",
  "m1671": "depends on each command-line tool's support for",
  "m1672": "(curl supports it; some tools may ignore it). For SOCKS5, enabling capture is recommended: the MITM proxy connects directly so tools need no awareness and proxying is reliable.",
  "m1673": "Proxy URL",
  "m1674": "socks5://user:pass@host:1080 or http://host:port (blank = direct)",
  "m1675": "Configured · All target traffic uses this proxy",
  "m1676": "Not configured · Target traffic connects directly",
  "m1677": "Operational constraint injection",
  "m1678": "When enabled, each task's",
  "m1679": "(allow/deny entries maintained in Task overview → Operational constraints) are included in the corresponding Agent system prompt to define exploration boundaries, such as testing only the current port or prohibiting brute force.",
  "m1680": "Injection can be controlled separately for",
  "m1681": "the planner",
  "m1682": "and",
  "m1683": "the worker",
  "m1684": "; both are on by default. Changes apply on the next read without rebuilding Agents. Disabled Agents no longer see constraints.",
  "m1685": "Inject into planner",
  "m1686": " · On",
  "m1687": " · Off",
  "m1688": "Inject into worker",
  "m1689": "Experimental features",
  "m1690": "Mechanisms still being validated, off by default. They may change Agent behavior or stability. Enable after understanding their effects.",
  "m1691": "noa context compression",
  "m1692": ": model-driven compression of long conversation history (norma v0.4.0). When enabled, the four Agent types (",
  "m1693": "planner / worker / main Agent / chat",
  "m1694": ") use noa context management instead of built-in compression. Original content is archived in the task working directory for review. Applies to subsequent runs without rebuilding Agents; disabling restores built-in compression immediately.",
  "m1695": "This is the web search",
  "m1696": "master switch and source configuration",
  "m1697": ". Once enabled, use",
  "m1698": "each Agent's configuration",
  "m1699": "to enable it individually",
  "m1700": "(returns titles, links, and snippets only; WebFetch retrieves full content). Web search",
  "m1701": "does not use",
  "m1702": "the recording proxy and is independent of traffic capture.",
  "m1703": "Available sources:",
  "m1704": "(no key required), ",
  "m1705": "Brave (free tier)",
  "m1706": "(requires Brave API key), ",
  "m1707": "(requires Tavily API key), or",
  "m1708": "(reuses the current LLM profile). With the master switch off, per-Agent web search toggles are unavailable.",
  "m1709": "Master switch on · Enable separately in each Agent's settings",
  "m1710": "Off · Agents cannot enable web search",
