  "m1721": "only supports official DeepSeek models",
  "m1722": ", and that profile",
  "m1723": "must use the Anthropic protocol",
  "m1724": "—DeepSeek's OpenAI-protocol endpoint does not support server-side search. Switching LLM profiles may break this source.",
