  "m2414": "# ARTIFEX Penetration Test Report — Acme Corp\n\n## Overview\n- Scope: acme.com (including www / admin / api / shop / vpn subdomains)\n- Confirmed findings: 6 (High 3 · Medium 3 · Low 2)\n- Engine mode: exploring\n\n## Key findings\n1. **[High] Default admin password** admin.acme.com admin/admin123 → full admin access.\n2. **[High] SQL injection** www.acme.com/search?q= → read access to acme_prod.\n3. **[High] IDOR** api.acme.com/v1/orders?id= → other users' orders exposed, including phone numbers and addresses.\n4. **[Medium] Reflected XSS**, **exposed .git source**, **no login rate limit**.\n\n## Recommendations\n- Require admin password changes and MFA; prohibit default credentials.\n- Use parameterized search queries and output encoding.\n- Enforce object-level API authorization and replace weak JWT secrets.\n\n> Demo report generated from mock data for interface demonstration only.",
