  "m1022": "刪除後,此分類的",
  "m1023": "個任務會移至「未分類」。任務資料不會被刪除。",
  "m1024": "輸入描述與目標",
  "m1025": "最多可連結 {p0} 個來源任務",
  "m1026": "任務已建立",
  "m1027": "建立失敗:",
  "m1028": "新增任務",
  "m1029": "輸入測試目標與目的。視需要展開進階設定。",
  "m1030": "名稱(選填)",
  "m1031": "為任務取一個可辨識的名稱,例如:Acme 網站評估",
  "m1032": "選填的單一分類,用於篩選與封存;不影響 Agent 執行。",
  "m1033": "測試目標與背景,例如:測試 example.com 網站",
  "m1034": "已上傳 {p0} 個檔案。絕對路徑已附加至描述(可編輯)",
  "m1035": "可選取多個檔案。其絕對路徑會附加至描述,讓 Workers 可用 Read/Bash 開啟",
  "m1036": "期望結果,例如:取得管理員存取權或伺服器存取權",
  "m1037": "關聯任務",
  "m1038": "最多可連結",
  "m1039": "個任務。以唯讀模式即時繼承其持久 blackboard、資產範圍與相關流量。新任務會寫入自己的 blackboard。",
  "m1040": "連結公司資產範圍",
  "m1041": "建立時,所選公司的既有資產會加入為測試資產。網域、IP、CIDR、ICP 與公司關鍵字為 Agent 提供範圍 context。這不會自動建立 intent 或覆寫執行目標。",
  "m1042": "任務資產封鎖/允許規則(選填)",
  "m1043": "僅適用於此任務,非全域規則。封鎖規則(含全域)會優先檢查;任何符合即禁止測試。若無封鎖規則符合且存在任務允許規則,則必須有允許規則符合。沒有允許規則時,不套用任何 allowlist。",
  "m1044": "LLM profile 鏈",
  "m1045": "依清單順序 failover。第一個 profile 為目前使用;只有明確的配額不足結果才會推進至下一個。",
  "m1046": "進階設定",
  "m1047": "逾時 · Heartbeat · 第一個 intent",
  "m1048": "任務逾時(分鐘,選填)",
  "m1049": "留白 = 無限制",
  "m1050": "到達期限時,開始優雅收尾:agents 回寫結果,planner 進行最終評估。任務以逾時狀態結束。",
  "m1051": "Planner heartbeat(分鐘)",
  "m1052": "預設:10",
  "m1053": "若自上一輪規劃或任務開始起經過此間隔且無其他觸發,會自動啟動一輪規劃,以恢復停滯並監督執行中的 Workers。最小值:10 分鐘。",
  "m1054": "直接派發第一個 intent(描述 + 目標)",
  "m1055": "建立時,將描述與目標作為單一 intent 派發,讓 Worker 無需等待初始規劃即可開始。planner 會於事後評估並補充結果。建議用於常由單一 Worker 解決的 CTF 類情境。停用時,先規劃後執行。",
  "m1056": "資產覆蓋功能",
  "m1057": "預設啟用:計算並顯示測試覆蓋率、在圖上顯示進度,並自動累加測試範圍。停用時,覆蓋率與圖上進度會隱藏,且 Agents 不會取得範圍工具。關聯的公司資產範圍不受影響。",
  "m1058": "建立中",
