  "m1250": "編輯規則",
  "m1251": "優先順序較高者先比對。套用第一條符合的規則；其後規則跳過",
  "m1252": "為規則命名",
  "m1253": "優先順序（數字較大者先比對）",
  "m1254": "比對目標",
  "m1255": "工具名稱（tool_name）",
