  "m1614": "將下載",
  "m1615": "，校驗 SHA256 並執行冒煙測試後再替換；失敗時保留目前版本。",
  "m1616": "已是最新版本。",
  "m1617": "Docker 更新只替換應用程式本身，不會替換 Playwright、Nmap 等隨附工具，且",
  "m1618": "重建容器會恢復映像內建版本；若要一併更新映像，請執行",
  "m1619": "正在重新啟動並套用新版本，請稍候，頁面會自動重新整理…",
  "m1620": "檢查更新",
  "m1621": "更新到 {p0}",
  "m1622": "立即更新",
  "m1623": "復原到上一個版本",
  "m1624": "一鍵更新依賴 supervisor 腳本重新啟動應用程式，請以",
  "m1625": "（Windows 上為",
  "m1626": "）啟動。直接執行二進位檔時，結束後不會自動重新啟動。",
  "m1627": "並行數必須是大於 0 的整數",
  "m1628": "Worker Agent 並行數已儲存（適用於後續啟動的任務）",
  "m1629": "Python 直譯器組態已儲存",
  "m1630": "Agent 自動流量綁定已啟用",
  "m1631": "Agent 自動流量綁定已停用",
  "m1632": "noa 上下文壓縮已啟用（適用於後續執行）",
  "m1633": "noa 上下文壓縮已停用（恢復內建壓縮）",
  "m1634": "網頁搜尋設定已儲存",
  "m1635": "Brave API key 已儲存",
  "m1636": "Tavily API key 已儲存",
