  "m1639": "全域代理已儲存",
  "m1640": "全域代理已清除（直連）",
  "m1641": "搜尋測試成功 · {p0} 回傳 {p1} 筆結果",
  "m1642": "搜尋測試失敗: ",
  "m1643": "未知錯誤",
  "m1644": "系統設定",
  "m1645": "全域執行期開關",
  "m1646": "啟用後，所有 Agent 的 HTTP 流量都會經過錄製代理並儲存。Agent 會取得 traffic_search / traffic_get 工具與代理設定，提示詞中包含代理說明。",
  "m1647": "停用時（預設），不錄製任何流量。Agent",
  "m1648": "不會",
  "m1649": "取得代理設定或流量工具，提示詞",
  "m1650": "不含",
  "m1651": "代理說明。切換後會立即重建 Agent 以套用變更。",
  "m1652": "已啟用 · 正在錄製流量並注入代理設定",
  "m1653": "已停用 · 不錄製、不注入代理",
  "m1654": "Agent 自動流量綁定",
  "m1655": "預設關閉。啟用後，漏洞建立時觸發的報告 Agent 會先檢視既有 HTTP 請求/回應並綁定流量，再撰寫報告。",
  "m1656": "檢視封包與額外的工具呼叫會增加 token 用量。",
  "m1657": "TCP、未錄製或未匹配的流量仍可回報。此功能不影響錄製、手動綁定或檢視已存證據。適用於下一輪 Agent；停用後會立即拒絕新的自動綁定。",
  "m1658": "已啟用 · 會增加 token 用量",
  "m1659": "已停用 · 仍可手動綁定",
  "m1660": "全域代理",
  "m1661": "所有 Agent 的",
  "m1662": "目標流量",
  "m1663": "皆經由此出站代理（隱藏來源 IP / 使用跳板機）。支援",
  "m1664": "，可選配",
  "m1665": "認證。留空 = 直連。",
  "m1666": "啟用時，可作為錄製代理的",
  "m1667": "上游",
  "m1668": "（轉發前流量仍會被錄製）。錄製關閉時，代理設定會直接注入 Agent 的 Bash/WebFetch。與網頁搜尋及 LLM 代理相互獨立。",
  "m1669": ": SOCKS5 搭配",
  "m1670": "錄製關閉",
  "m1671": "取決於各命令列工具對",
  "m1672": "的支援（curl 支援；部分工具可能忽略）。SOCKS5 建議啟用錄製：MITM 代理直接連線，工具無需感知且代理可靠。",
  "m1673": "代理 URL",
  "m1674": "socks5://user:pass@host:1080 或 http://host:port（留空 = 直連）",
  "m1675": "已設定 · 所有目標流量皆經由此代理",
  "m1676": "未設定 · 目標流量直連",
  "m1677": "行動約束注入",
  "m1678": "啟用後，每個任務的",
  "m1679": "（允許/拒絕條目於任務總覽 → 行動約束維護）會寫入對應 Agent 的系統提示詞，以界定探索邊界，例如僅測試目前連接埠或禁止暴力破解。",
  "m1680": "可分別控制注入到",
  "m1681": "planner",
  "m1682": "與",
  "m1683": "worker",
  "m1684": "；兩者預設開啟。變更於下次讀取時生效，無需重建 Agent；停用的 Agent 不再看到約束。",
  "m1685": "注入 planner",
  "m1686": " · 開",
  "m1687": " · 關",
  "m1688": "注入 worker",
  "m1689": "實驗性功能",
  "m1690": "仍在驗證中的機制，預設關閉；可能改變 Agent 行為或穩定性。請在了解其影響後再啟用。",
  "m1691": "noa 上下文壓縮",
  "m1692": "：以模型驅動方式壓縮長對話歷史（norma v0.4.0）。啟用後，四類 Agent（",
  "m1693": "planner / worker / 主 Agent / 聊天",
  "m1694": "）改用 noa 上下文管理而非內建壓縮。原文會封存在任務工作目錄供查閱。適用於後續執行，無需重建 Agent；停用後立即恢復內建壓縮。",
  "m1695": "此處為網頁搜尋的",
  "m1696": "總開關與來源設定",
  "m1697": "。啟用後，請至",
  "m1698": "各 Agent 的設定",
  "m1699": "分別開啟",
  "m1700": "（只回傳標題、連結與摘要；WebFetch 可取得完整內容）。網頁搜尋",
  "m1701": "不使用",
  "m1702": "錄製代理，與流量錄製相互獨立。",
  "m1703": "可用來源：",
  "m1704": "（無需 key），",
  "m1705": "Brave（免費額度）",
  "m1706": "（需 Brave API key），",
  "m1707": "（需 Tavily API key），或",
  "m1708": "（沿用目前的 LLM 設定檔）。總開關關閉時，各 Agent 的網頁搜尋開關不可用。",
  "m1709": "總開關已開 · 請在各 Agent 設定中分別啟用",
  "m1710": "關閉 · Agent 無法啟用網頁搜尋",
  "m1711": "搜尋來源",
  "m1712": "選擇來源",
  "m1713": "DuckDuckGo（ddgs · 免費、無需 key）",
  "m1714": "Brave（免費額度 · 需 key）",
  "m1715": "Tavily（需 key）",
  "m1716": "DeepSeek（官方）",
  "m1717": "DeepSeek 官方網頁搜尋",
  "m1718": "此來源直接沿用",
  "m1719": "目前生效的 LLM 設定檔",
  "m1720": "，因此",
  "m1721": "僅支援 DeepSeek 官方模型",
  "m1722": "，且該設定檔",
  "m1723": "必須使用 Anthropic 協定",
  "m1724": "—DeepSeek 的 OpenAI 協定端點不支援伺服器端搜尋。切換 LLM 設定檔可能使此來源失效。",
  "m1725": "與其他來源不同，搜尋是在",
  "m1726": "DeepSeek 的伺服器上執行",
  "m1727": "：每次搜尋都增加一次模型呼叫與 token 成本。搜尋請求",
  "m1728": "不經過上方出站代理",
  "m1729": "，且",
  "m1730": "不計入流量錄製",
  "m1731": "。結果只含",
  "m1732": "標題與連結",
  "m1733": "（無摘要）。完整內容請用 WebFetch。",
  "m1734": "以上要求須自行確認，系統不會強制檢查。可執行下方「測試搜尋」確認實際可用性。",
  "m1735": "已設定（留空則保持現值）",
  "m1736": "輸入 Brave API key",
  "m1737": "已選擇 Brave 但未設定 key；儲存 key 前搜尋保持停用。",
