  "m2413": "未授權",
  "m2414": "# ARTIFEX 滲透測試報告 — Acme Corp\\n\\n## 概述\\n- 範圍：acme.com（含 www / admin / api / shop / vpn 子網域）\\n- 已確認發現：6 項（高危 3 · 中危 3 · 低危 2）\\n- 引擎模式：exploring\\n\\n## 關鍵發現\\n1. **[高危] 預設管理員密碼** admin.acme.com admin/admin123 → 完整管理員存取權。\\n2. **[高危] SQL 注入** www.acme.com/search?q= → 可讀取 acme_prod。\\n3. **[高危] IDOR** api.acme.com/v1/orders?id= → 洩露其他使用者的訂單，含電話號碼與地址。\\n4. **[中危] 反射型 XSS**、**暴露的 .git 原始碼**、**登入無速率限制**。\\n\\n## 建議\\n- 要求管理員密碼更換並啟用 MFA；禁止預設憑證。\\n- 使用參數化查詢與輸出編碼。\\n- 強制執行物件層級 API 授權並更換弱 JWT 密鑰。\\n\\n> 本示範報告由模擬資料產生，僅供介面示範之用。",
  "m2415": "上傳失敗：{p0}",
