  "m2436": "評估 api.acme.com 訂單與使用者端點的 IDOR 與注入風險。",
  "m2437": "shop.acme.com 支付與訂單流程",
  "m2438": "評估支付與訂單端點的授權、金額竄改與競態條件風險。",
  "m2439": "外部暴露面偵察（VPN / 邊界服務）",
