  "m2648": "Kerberoasting 取得 svc_sql 密碼；已記錄至圖譜供網域控制站評估。",
  "m2649": "svc_deploy 來自 Jenkins 憑證。檢查群組成員資格；屬於 Domain Admins 即可對 DC01 直接 psexec。",
