  "m2663": "已確認。路徑：shop Fastjson RCE → DMZ 提權 → Jenkins 網域憑證 → svc_deploy 屬 Domain Admins → psexec 取得 DC01 SYSTEM → secretsdump 匯出網域雜湊。四項目標皆已達成或進行中。",
