  "m2712": "# 複核摘要\\n\\n本輪驗證已完成。請整理現有證據與後續建議。",
  "m2713": "[Model] 將現有結論寫入本機報告，且不變更業務資料。",
  "m2714": "彙整已完成的檢查，並將結論與證據引用寫入 reports/summary.md。\\n保留未驗證項目，且不得變更業務資料。",
  "m2715": "將本輪現有證據彙整為複核摘要。",
  "m2716": "讀取 3 筆證據引用。\\n記錄包含請求時間、結果摘要與本機檔案位置。",
  "m2717": "已成功寫入 reports/summary.md\\n已寫入 68 個字元。",
  "m2718": "確認備份資料表的用途；刪除前先確認。",
  "m2719": "[Model] 可能是備份資料表；無法確認是否包含正式環境資料。",
  "m2720": "Acme admin 入口討論",
  "m2721": "API 授權面複核",
  "m2722": "內部橫向移動 · DMZ 至網域控制站的路徑規劃",
  "m2723": "admin 在哪裡？從哪裡開始？",
  "m2724": "檢查 admin.acme.com 的登入技術棧與防護（CAPTCHA/速率限制），再選擇預設憑證或字典。",
  "m2725": "Element-UI admin，有 CSRF token 但無 CAPTCHA。",
  "m2726": "連續五次嘗試皆無鎖定/CAPTCHA，表示沒有速率限制；可進行暴力破解。",
  "m2727": "結論：Element-UI admin 無 CAPTCHA 或速率限制。先試預設憑證（admin/admin、admin/admin123、admin/123456），必要時再試 top1000 字典。已將高優先級預設憑證 intent 指派給 Worker。",
  "m2728": "成功了嗎？",
  "m2729": "成功。admin/admin123 開啟了主控台。已記錄為高嚴重度發現，並作為 admin 存取權的證明。下一步是敏感使用者資料（目標 2）。",
  "m2730": "複核 api.acme.com 的授權風險。",
  "m2731": "檢查 API 驗證與關鍵端點行為，再評估 IDOR/JWT 風險。",
  "m2732": "標準使用者 token 可用。",
  "m2733": "echo '<jwt>' | cut -d. -f1 | base64 -d; # 檢查演算法",
  "m2734": "HS256 對稱簽章；弱密鑰可離線破解與偽造。",
  "m2735": "兩條路徑：/v1/orders?id= 的連續 ID 顯示可能存在 IDOR；換個 ID 試試。HS256 JWT 可能允許弱密鑰破解與任意 sub 偽造。兩者皆有 intent。先做 IDOR，因為成本低且直接。",
  "m2736": "我們已有 shell。接下來如何評估內部網路？",
  "m2737": "www-data 權限不足以進行橫向移動。先檢查本機提權，取得 root 後再透過 DMZ 樞紐進行發現。",
  "m2738": "先提權：sudo -l 顯示 python3 免密碼。然後透過 DMZ 樞紐以 fscan 發現內部主機，重點關注網域控制站與 CI/CD 伺服器。",
  "m2739": "發現三台內部主機；Jenkins 8080 埠開放。有用嗎？",
  "m2740": "/script 無需驗證即可直接存取。",
  "m2741": "是的，未驗證的 Script Console 允許 Groovy RCE。提示已將此主機設為優先。取得存取後，檢查憑證儲存庫中的網域帳號。",
  "m2742": "已取得網域憑證；svc_deploy 屬於 Domain Admins。直接打 DC01？",
  "m2743": "是的。屬於 Domain Admins 的 svc_deploy 可用 psexec 存取 DC01，再用 secretsdump 取得網域雜湊。secretsdump 會觸發攔截規則；本 demo 已事先核准。",
  "m2744": "目標已達成。總結整條鏈路。",
  "m2745": "完整鏈路：\\n1. .git 外洩 → 原始碼審查與硬編碼憑證\\n2. Shop Fastjson RCE → DMZ 反彈 shell\\n3. Sudo 提權 → root 落腳點\\n4. 內部發現 → DC01/FS01/Jenkins\\n5. 未驗證 Jenkins → svc_deploy 網域憑證\\n6. Kerberoasting → svc_sql 密碼\\n7. svc_deploy 屬 Domain Admins → psexec DC01 → secretsdump 網域雜湊\\n\\n四項目標全部達成；17 項發現（7 高 / 4 中 / 2 低 + 8 項內部鏈條項目）。",
  "m2746": "Acme 首頁",
  "m2747": "Admin 登入",
  "m2748": "探測 www.acme.com search 的 SQL 注入",
  "m2749": "枚舉 api.acme.com 的 IDOR",
  "m2750": "search?q= 可注入；回應顯示 MySQL 語法錯誤",
  "m2751": "[High] SQL 注入 www.acme.com/search?q=",
  "m2752": "# 工作區筆記\\n\\n（Demo）工作區根目錄中的此範例檔案可線上編輯並儲存。\\n",
  "m2753": "<!-- (demo) 擷取的回應主體節錄 -->\\n<html><body>MySQL error near ''1'='1'</body></html>\\n",
  "m2754": "（Demo）此處省略原始 LLM 對話範例。",
  "m2755": "HTTP/1.1 200 OK\\nContent-Length: 12034\\n<html>… 搜尋結果 …</html>",
  "m2756": "429 Too Many Requests（退避後重試）",
  "m2757": "你是已授權滲透測試系統的 Worker…（已省略）",
  "m2758": "僅執行 system prompt 中的 intent，產出 facts，完成後即停止。",
  "m2759": "探測 search?q= 注入，從 error-based payload 開始。",
  "m2760": "在目標環境中執行 shell 命令並回傳其輸出。",
  "m2761": "data: {\\\"type\\\":\\\"content_block_delta\\\",\\\"index\\\":0,\\\"delta\\\":{\\\"type\\\":\\\"text_delta\\\",\\\"text\\\":\\\"在 search?q= 上探測注入。\\\"}}",
  "m2762": "q 中帶入注入 payload；回應回傳 MSSQL 錯誤。",
  "m2763": "自己的訂單 id=1001 作為正常基準。",
  "m2764": "改為 id=1002 即可讀取其他使用者的訂單。",
  "m2765": "Fastjson @type JNDI payload 觸發回呼。",
  "m2766": "第二次請求確認命令執行。",
  "m2767": "Jenkins Script Console 無需驗證即可觸及。",
  "m2768": "scriptText 執行 Groovy 並回傳 SYSTEM。",
  "m2769": "psexec 以 svc_deploy 登入 DC01。",
  "m2770": "{\\\"order_id\\\":1002,\\\"user_id\\\":77,\\\"amount\\\":1299.00,\\\"address\\\":\\\"北京市朝陽區****\\\",\\\"phone\\\":\\\"138****6021\\\"}",
  "m2771": "本 demo 未執行真實驗證；無法確認目前的漏洞狀態。",
